//! `smin`, from OpenBLAS `kernel/arm/amax_vfp.S`, as expanded for armv6, armv7, cortexa15, cortexa9 (hf); armv6, armv7, cortexa15, cortexa9 (sf).
//!
//! Generated by `tools/blas_asm/gen.zig`: the assembly of that source,
//! unchanged, as a naked function per core; the lines only some cores
//! have are under `parts`. Re-derive it rather than editing it.

const std = @import("std");

/// Each function's core and variant.
const keys = [_][2][]const u8{
    .{ "armv6", "hf" },
    .{ "armv7", "hf" },
    .{ "cortexa15", "hf" },
    .{ "cortexa9", "hf" },
    .{ "armv6", "sf" },
    .{ "armv7", "sf" },
    .{ "cortexa15", "sf" },
    .{ "cortexa9", "sf" },
};

/// Which parts each key's function has: `__bk`'s arguments.
const parts = [_][]const u8{
    "0",
    "0",
    "0",
    "0",
    "1",
    "1",
    "1",
    "1",
};

/// Whether any build of `core` uses this file.
pub fn serves(comptime core: []const u8) bool {
    inline for (keys) |key| if (comptime std.mem.eql(u8, key[0], core)) return true;
    return false;
}

/// The function for `core` built as `variant`, if this file has it.
pub fn kernel(comptime core: []const u8, comptime variant: []const u8) ?type {
    inline for (keys, 0..) |key, i| {
        if (comptime std.mem.eql(u8, key[0], core) and std.mem.eql(u8, key[1], variant)) return Body(parts[i]);
    }
    return null;
}

/// The functions' one text, a macro whose parameters select the parts.
const text =
    \\ .macro __bk bp0
    \\ .macro INIT_F
    \\ vldmia.f32 r1!, { s0 }
    \\ nop
    \\ .endm
    \\ .macro KERNEL_F1
    \\ vldmia.f32 r1!, { s4 }
    \\ nop
    \\ vcmpe.f32 s4, s0
    \\ vmrs APSR_nzcv, fpscr
    \\ vmovmi.f32 s0, s4
    \\ .endm
    \\ .macro INIT_S
    \\ vldmia.f32 r1, { s0 }
    \\ nop
    \\ add r1, r1, r2
    \\ .endm
    \\ .macro KERNEL_S1
    \\ vldmia.f32 r1, { s4 }
    \\ nop
    \\ vcmpe.f32 s4, s0
    \\ vmrs APSR_nzcv, fpscr
    \\ vmovmi.f32 s0, s4
    \\ add r1, r1, r2
    \\ .endm
    \\ .arm
    \\ .align 5
    \\ movs r12, #0
    \\ vmov s0, r12
    \\ cmp r0, #0
    \\ ble 20008f
    \\ cmp r2, #0
    \\ beq 20008f
    \\ cmp r2, #1
    \\ bne 20004f
    \\ 20000:
    \\ INIT_F
    \\ subs r0, r0 , #1
    \\ ble 20008f
    \\ asrs r12, r0, #2
    \\ ble 20002f
    \\ .align 5
    \\ 20001:
    \\ pld [ r1, #512 ]
    \\ KERNEL_F1
    \\ KERNEL_F1
    \\ KERNEL_F1
    \\ KERNEL_F1
    \\ subs r12, r12, #1
    \\ ble 20002f
    \\ KERNEL_F1
    \\ KERNEL_F1
    \\ KERNEL_F1
    \\ KERNEL_F1
    \\ subs r12, r12, #1
    \\ bne 20001b
    \\ 20002:
    \\ ands r12, r0, #3
    \\ ble 20008f
    \\ 20003:
    \\ KERNEL_F1
    \\ subs r12, r12, #1
    \\ bne 20003b
    \\ b 20008f
    \\ 20004:
    \\ lsl r2, r2, #2
    \\ INIT_S
    \\ subs r0, r0 , #1
    \\ ble 20008f
    \\ asrs r12, r0, #2
    \\ ble 20006f
    \\ .align 5
    \\ 20005:
    \\ KERNEL_S1
    \\ KERNEL_S1
    \\ KERNEL_S1
    \\ KERNEL_S1
    \\ subs r12, r12, #1
    \\ bne 20005b
    \\ 20006:
    \\ ands r12, r0, #3
    \\ ble 20008f
    \\ 20007:
    \\ KERNEL_S1
    \\ subs r12, r12, #1
    \\ bne 20007b
    \\ 20008:
    \\ .if \bp0
    \\ vmov r0, s0
    \\ .endif
    \\ bx lr
    \\ .purgem INIT_F
    \\ .purgem KERNEL_F1
    \\ .purgem INIT_S
    \\ .purgem KERNEL_S1
    \\ .endm
    \\
;

fn Body(comptime args: []const u8) type {
    return struct {
        pub fn smin() callconv(.naked) void {
            asm volatile (text ++ (" __bk " ++ args ++ "\n .purgem __bk\n"));
        }
    };
}
